      const base = katakana ? String.fromCharCode(plain.charCodeAt(0) + 0x60) : plain;
      const letter = (base + (semi ? '゚' : '゙')).normalize('NFC');
      const mark = semi ? '右上多一個小圈（半濁點）' : '右上多兩點（濁點）';
